draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Book
  ctx.fillStyle = '#663300';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.stroke();

  // Stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-120);
  ctx.lineTo(W/2-30, H/2-90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-120);
  ctx.lineTo(W/2+30, H/2-90);
  ctx.stroke();

  // Applying wisdom
  ctx.fillStyle = '#000000';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Applying', W/2, H/2-70 + 20*Math.sin(t));
  ctx.fillText('Wisdom', W/2, H/2-40 + 20*Math.sin(t));

  // Lesson life
  ctx.textAlign = 'left';
  ctx.textBaseline = 'bottom';
  ctx.fillText('Lesson', W/2-50 + 10*Math.cos(t), H/2);
  ctx.fillText('Life', W/2-30 + 10*Math.cos(t), H/2);

  ctx.restore();
}
